import json,collections,re
enc={}
for l in open('Encounter.ndjson'):
    e=json.loads(l); enc[e['id']]=e
cond=[json.loads(l) for l in open('Condition.ndjson')]
pats=json.load(open('patients.json'))['resources']
alive={p['id'] for p in pats if not p.get('deceasedDateTime')}
hits=collections.defaultdict(list)
for c in cond:
    disp=' '.join(cc.get('display','') for cc in c['code']['coding'])
    if re.search(r'fibrillation|flutter', disp, re.I):
        pid=c['subject']['reference'].split('/')[-1]
        e=enc.get(c.get('encounter',{}).get('reference','').split('/')[-1],{})
        hits[pid].append((e.get('period',{}).get('start','?')[:10], disp, c['id']))
for pid in hits:
    print(('ALIVE' if pid in alive else 'DEAD'), pid)
    for h in sorted(hits[pid]): print('   ',h)
EOF

