import sys,numpy as np,json
sys.path.insert(0,'/work')
from ecg2 import *
import warnings; warnings.filterwarnings('ignore')

def aplot(y,width=150,height=16,label='',marks=None):
    y=np.asarray(y,float); n=len(y)
    idx=np.linspace(0,n-1,width).astype(int); v=y[idx]
    lo,hi=v.min(),v.max()
    if hi-lo<1e-9: hi=lo+1
    g=[[' ']*width for _ in range(height)]
    for c,val in enumerate(v):
        r=int((hi-val)/(hi-lo)*(height-1)); g[r][c]='.'
    if marks:
        for k,p in marks.items():
            c=min(max(int(p/(n-1)*(width-1)),0),width-1); g[height-1][c]=k
    print(f'-- {label} [{lo:.2f},{hi:.2f}]')
    for r in g: print(''.join(r))

def show(eid, strip=True):
    o,M,X=analyze(eid)
    print('='*150)
    print(eid, {k:v for k,v in o.items() if k!='_'})
    d=o['_']
    mk={'o':d['qon'],'f':d['qoff'],'t':d['tp'],'e':int(d['te'])}
    if d['pon'] is not None: mk['p']=d['pon']; mk['q']=d['poff']
    aplot(M['II'],label='medbeat II',marks=mk)
    aplot(M['V1'],label='medbeat V1',marks=mk)
    if strip:
        aplot(filt(X['II']),label='strip II 10s')
        aplot(filt(X['V1']),label='strip V1 10s')
if __name__=='__main__':
    for e in sys.argv[1:]: show(e)
