COND={'102280728':['FIRST_DEGREE_AV_BLOCK'],'104941853':['LBBB','FIRST_DEGREE_AV_BLOCK']}
PCOND={'106516875':['RBBB'],'103686933':['LBBB']}
EXPL={}
