    pr=None if rh in ('AF','ATRIAL_FLUTTER') else r['pr']
    ch=[]
    if pv:
        rp=res[pv['ecg']]
        prh=PRHY.get(pv['ecg'],RHY.get(pv['ecg'],'SINUS'))
        pcond=PCOND.get(pv['ecg'],[])
        if rh=='AF' and prh!='AF': ch.append('NEW_AF')
        if prh=='AF' and rh!='AF': ch.append('RESOLVED_AF')
        if rh=='ATRIAL_FLUTTER' and prh!='ATRIAL_FLUTTER': ch.append('NEW_ATRIAL_FLUTTER')
        if prh=='ATRIAL_FLUTTER' and rh!='ATRIAL_FLUTTER': ch.append('RESOLVED_ATRIAL_FLUTTER')
        if rh=='PACED' and prh!='PACED': ch.append('NEW_PACED_RHYTHM')
        if prh=='PACED' and rh!='PACED': ch.append('RESOLVED_PACED_RHYTHM')
        bb=set(x for x in cond if x in ('RBBB','LBBB')); pbb=set(x for x in pcond if x in ('RBBB','LBBB'))
        if bb-pbb: ch.append('NEW_BUNDLE_BRANCH_BLOCK')
        if pbb-bb: ch.append('RESOLVED_BUNDLE_BRANCH_BLOCK')
        d=r['qtc']-rp['qtc']
        if d>=60: ch.append('QTC_INCREASE_60')
        if d<=-60: ch.append('QTC_DECREASE_60')
    out.append(dict(patient=p['id'],ecg=c['ecg'],date=c['time'],rhythm=rh,ventricular_rate=r['rate'],
