                    prior_date=(pv['time'] if pv else None),
                    prior_qtc=(res[pv['ecg']]['qtc'] if pv else None),changes=ch))
json.dump(out,open('interps.json','w'),indent=1)
for o in out: print(o['patient'][:8],o['ecg'],o['date'][:10],o['rhythm'],o['ventricular_rate'],o['pr_ms'],o['qrs_ms'],o['qtc_ms'],o['axis'],o['axdeg'],o['conduction'],o['prior_ecg'],o['prior_qtc'],o['changes'])
